# name: heard_all_true_max_point_concentration
# description: Mean maximum points placed on any single object on trials where the heard word is true of all four objects in the display, testing whether the model under- or over-predicts trial-level betting concentration when semantics rules out no referent.
def test_statistic(df):
    heard_mask = df["heard"].notna()
    sub = df[heard_mask]
    if len(sub) == 0:
        return 0.0
    scenes = sub[["objects", "heard"]].drop_duplicates()
    all_true_scenes = set()
    for objs_str, h_val in zip(scenes["objects"], scenes["heard"]):
        objs = json.loads(objs_str)
        h = int(h_val)
        if all(o[h] == 1 for o in objs):
            all_true_scenes.add((objs_str, h))
    keys = list(zip(sub["objects"], sub["heard"].astype(int)))
    valid_idx = [i for i, k in enumerate(keys) if k in all_true_scenes]
    if not valid_idx:
        return 0.0
    pts_series = sub["points"].iloc[valid_idx]
    unique_pts = pts_series.unique()
    pts_map = {s: max(json.loads(s)) for s in unique_pts}
    vals = [pts_map[s] for s in pts_series]
    return float(np.mean(vals))

# name: heard_false_referent_points_leakage
# description: Mean total points allocated to semantically false objects (objects lacking the heard feature) on trials where a word was heard and at least one object lacks that feature, testing whether the model's uniform lapse and Dirichlet-multinomial link mispredict points given to false referents.
def test_statistic(df):
    heard_mask = df["heard"].notna()
    sub = df[heard_mask]
    if len(sub) == 0:
        return 0.0
    scenes = sub[["objects", "heard"]].drop_duplicates()
    false_map = {}
    for objs_str, h_val in zip(scenes["objects"], scenes["heard"]):
        objs = json.loads(objs_str)
        h = int(h_val)
        false_indices = [i for i, o in enumerate(objs) if o[h] == 0]
        if len(false_indices) >= 1:
            false_map[(objs_str, h)] = false_indices
    keys = list(zip(sub["objects"], sub["heard"].astype(int)))
    matched = [false_map.get(k, None) for k in keys]
    valid_idx = [i for i, m in enumerate(matched) if m is not None]
    if not valid_idx:
        return 0.0
    pts_series = sub["points"].iloc[valid_idx]
    unique_pts = pts_series.unique()
    pts_map = {s: json.loads(s) for s in unique_pts}
    vals = []
    for s, idx in zip(pts_series, valid_idx):
        p = pts_map[s]
        f_indices = matched[idx]
        vals.append(sum(p[i] for i in f_indices))
    return float(np.mean(vals))

# name: heard_max_feature_competitor_points
# description: Mean points allocated to the most feature-rich true referent in heard-word scenes where multiple objects satisfy the heard word and differ in feature count, testing whether depth-2 RSA over-eliminates complex competitors via scalar implicature.
def test_statistic(df):
    heard_mask = df["heard"].notna()
    sub = df[heard_mask]
    if len(sub) == 0:
        return 0.0
    scenes = sub[["objects", "heard"]].drop_duplicates()
    target_idx_map = {}
    for objs_str, h_val in zip(scenes["objects"], scenes["heard"]):
        objs = json.loads(objs_str)
        h = int(h_val)
        true_indices = [i for i, o in enumerate(objs) if o[h] == 1]
        if len(true_indices) >= 2:
            fcounts = [sum(objs[i]) for i in true_indices]
            max_f = max(fcounts)
            min_f = min(fcounts)
            if max_f > min_f:
                max_indices = [i for i in true_indices if sum(objs[i]) == max_f]
                if len(max_indices) == 1:
                    target_idx_map[(objs_str, h)] = max_indices[0]
    keys = list(zip(sub["objects"], sub["heard"].astype(int)))
    t_idx = np.array([target_idx_map.get(k, -1) for k in keys], dtype=np.int64)
    valid = t_idx >= 0
    if not np.any(valid):
        return 0.0
    pts_series = sub["points"].iloc[np.flatnonzero(valid)]
    t_valid = t_idx[valid]
    unique_pts = pts_series.unique()
    pts_map = {s: json.loads(s) for s in unique_pts}
    parsed = [pts_map[s] for s in pts_series]
    vals = [row[idx] for row, idx in zip(parsed, t_valid)]
    return float(np.mean(vals))

# name: prior_two_singletons_with_duplicate_pair_diff
# description: Mean point difference between the sparser singleton and the richer singleton on prior trials (no word heard) that contain two distinct singletons alongside an identical pair of duplicate objects, testing whether the prior's distinctiveness and feature-count weights distort preference between the two singletons.
def test_statistic(df):
    prior_mask = df["heard"].isna()
    sub = df[prior_mask]
    if len(sub) == 0:
        return 0.0
    scenes = sub["objects"].unique()
    scene_map = {}
    for objs_str in scenes:
        objs = json.loads(objs_str)
        dup_counts = [sum(1 for o2 in objs if o2 == objs[i]) for i in range(len(objs))]
        sings = [i for i, c in enumerate(dup_counts) if c == 1]
        dups = [i for i, c in enumerate(dup_counts) if c == 2]
        if len(sings) == 2 and len(dups) == 2:
            s0, s1 = sings[0], sings[1]
            if sum(objs[s0]) <= sum(objs[s1]):
                scene_map[objs_str] = (s0, s1)
            else:
                scene_map[objs_str] = (s1, s0)
    matched = [scene_map.get(s, None) for s in sub["objects"]]
    valid_idx = [i for i, m in enumerate(matched) if m is not None]
    if not valid_idx:
        return 0.0
    pts_series = sub["points"].iloc[valid_idx]
    unique_pts = pts_series.unique()
    pts_map = {s: json.loads(s) for s in unique_pts}
    vals = []
    for s, idx in zip(pts_series, valid_idx):
        p = pts_map[s]
        s_low, s_high = matched[idx]
        vals.append(p[s_low] - p[s_high])
    return float(np.mean(vals))

# name: prior_odd_one_out_rich_vs_sparse_asymmetry
# description: Difference on prior trials between the mean points given to a unique all-features singleton (against featureless duplicates) and the mean points given to a unique featureless singleton (against all-features duplicates), testing feature-count asymmetry when singleton and distinctiveness cues are symmetric.
def test_statistic(df):
    prior_mask = df["heard"].isna()
    sub = df[prior_mask]
    if len(sub) == 0:
        return 0.0
    scenes = sub["objects"].unique()
    scene_map = {}
    for objs_str in scenes:
        objs = json.loads(objs_str)
        dup_counts = [sum(1 for o2 in objs if o2 == objs[i]) for i in range(len(objs))]
        sings = [i for i, c in enumerate(dup_counts) if c == 1]
        if len(sings) == 1 and len(objs) >= 3:
            s_idx = sings[0]
            other_idx = [i for i in range(len(objs)) if i != s_idx][0]
            f_sing = sum(objs[s_idx])
            f_other = sum(objs[other_idx])
            if f_sing > f_other and f_other == 0:
                scene_map[objs_str] = ("rich_sing", s_idx)
            elif f_sing == 0 and f_other > 0:
                scene_map[objs_str] = ("sparse_sing", s_idx)
    matched = [scene_map.get(s, None) for s in sub["objects"]]
    valid_idx = [i for i, m in enumerate(matched) if m is not None]
    if not valid_idx:
        return 0.0
    pts_series = sub["points"].iloc[valid_idx]
    unique_pts = pts_series.unique()
    pts_map = {s: json.loads(s) for s in unique_pts}
    rich_vals = []
    sparse_vals = []
    for s, idx in zip(pts_series, valid_idx):
        p = pts_map[s]
        kind, s_idx = matched[idx]
        if kind == "rich_sing":
            rich_vals.append(p[s_idx])
        else:
            sparse_vals.append(p[s_idx])
    if not rich_vals or not sparse_vals:
        return 0.0
    return float(np.mean(rich_vals) - np.mean(sparse_vals))

# name: prior_all_singleton_featureless_vs_rich_diff
# description: Mean point difference between the least feature-rich object and the all-features object on prior trials (no word heard) where all four objects are unique singletons, testing whether the model's prior over-favors sparse/distinctive objects over feature-rich objects when singleton status is equal.
def test_statistic(df):
    prior_mask = df["heard"].isna()
    sub = df[prior_mask]
    if len(sub) == 0:
        return 0.0
    scenes = sub["objects"].unique()
    scene_map = {}
    for objs_str in scenes:
        objs = json.loads(objs_str)
        dup_counts = [sum(1 for o2 in objs if o2 == objs[i]) for i in range(len(objs))]
        if all(c == 1 for c in dup_counts) and len(objs) >= 2:
            fcounts = [sum(o) for o in objs]
            min_i = int(np.argmin(fcounts))
            max_i = int(np.argmax(fcounts))
            if min_i != max_i:
                scene_map[objs_str] = (min_i, max_i)
    matched = [scene_map.get(s, None) for s in sub["objects"]]
    valid_idx = [i for i, m in enumerate(matched) if m is not None]
    if not valid_idx:
        return 0.0
    pts_series = sub["points"].iloc[valid_idx]
    unique_pts = pts_series.unique()
    pts_map = {s: json.loads(s) for s in unique_pts}
    vals = []
    for s, idx in zip(pts_series, valid_idx):
        p = pts_map[s]
        min_i, max_i = matched[idx]
        vals.append(p[min_i] - p[max_i])
    return float(np.mean(vals))
